# Write only explicitly authored styles. The remaining leaves are authored in the next pass.
def emit(leaf,origin,body):
 metadata=json.loads((K/'elements'/leaf/'element.json').read_text())
 taxonomy=json.loads(Path('/workspace/work/reference/contract/taxonomy.json').read_text())
 roots=next(x['roots'] for x in taxonomy['contracts'] if x['id']==metadata['contract'])
 body=body.replace('CORNERSINK',','.join(f'linear-gradient(var(--ink),var(--ink)) {x} {y}/7px 7px no-repeat' for x,y in [('0','0'),('100%','0'),('0','100%'),('100%','100%')])).replace('CORNERS',corners())
 blocks=[]
 for cl in roots:
  selector=f'.{cl}[data-el="vectorbox-{leaf}"]'
  blocks.append(common.replace('R',selector)+'\n'+body.replace('R',selector))
 (K/'elements'/leaf/'element.css').write_text(f'/* Source {origin}. One representative base; contract variants only. */\n'+'\n'.join(blocks)+'\n')
if __name__=='__main__':
 import sys
 selected=sys.argv[1:] or list(styles)
 for leaf in selected:
  origin,body=styles[leaf];emit(leaf,origin,body)
 print('Fresh CSS authored:',','.join(selected))
